<?php

declare(strict_types=1);

namespace Tests\Generated\MyCrud\FilmCategory;

use CodeIgniter\Test\CIUnitTestCase;

/**
 * Structural smoke test generated by myCrudCI4.
 *
 * Verifies that the components required by the architecture are published and
 * loadable through the autoloader. It does not access application data.
 */
final class FilmCategoryStructureTest extends CIUnitTestCase
{
    private const EXPECTED_CLASSES = array (
  0 => 'App\\Models\\FilmCategoryModel',
  1 => 'App\\Controllers\\FilmCategoryController',
  2 => 'App\\Validation\\FilmCategoryRules',
  3 => 'App\\Entities\\FilmCategoryEntity',
  4 => 'App\\Services\\FilmCategoryService',
  5 => 'App\\Controllers\\Api\\V1\\FilmCategoryApiController',
  6 => 'App\\API\\Resources\\FilmCategoryResource',
  7 => 'App\\Validation\\FilmCategoryApiRules',
);

    public function testGeneratedClassesAreAutoloadable(): void
    {
        foreach (self::EXPECTED_CLASSES as $class) {
            $this->assertTrue(
                class_exists($class),
                'Generated class is not autoloadable: ' . $class
            );
        }
    }
}
